"""Client for the geocoder dependency, fake or real (docs/adr/0006)."""

import os

import httpx

TIMEOUT_SECONDS = 2.0


class GeocoderUnavailable(Exception):
    pass


class GeocoderAmbiguous(Exception):
    def __init__(self, candidates: list[str]) -> None:
        super().__init__(f"ambiguous venue: {candidates}")
        self.candidates = candidates


def geocode(venue: str) -> tuple[float | None, float | None]:
    base_url = os.environ["GEOCODER_URL"]
    try:
        response = httpx.get(
            f"{base_url}/search",
            params={"q": venue, "format": "jsonv2", "limit": 1},
            timeout=TIMEOUT_SECONDS,
        )
    except httpx.HTTPError as exc:
        raise GeocoderUnavailable(str(exc)) from exc
    if response.status_code >= 500:
        raise GeocoderUnavailable(f"status {response.status_code}")
    try:
        results = response.json()
    except Exception as exc:
        raise GeocoderUnavailable(f"malformed geocoder response: {exc}") from exc
    if not isinstance(results, list):
        raise GeocoderUnavailable("malformed geocoder response: expected list")
    if not results:
        return None, None
    if len(results) > 1:
        candidates = [m.get("display_name", "") for m in results]
        raise GeocoderAmbiguous(candidates)
    match = results[0]
    try:
        return float(match["lat"]), float(match["lon"])
    except (KeyError, ValueError, TypeError) as exc:
        raise GeocoderUnavailable(f"malformed geocoder response: {exc}") from exc

